{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "In humans, the prostaglandin analogue nocloprost had an absolute oral bioavailability of about 2% after oral administration, independent of dose, demonstrating that prostaglandin-like bicyclic fatty acids can undergo extensive first-pass metabolism and very low systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Iloprost, another prostaglandin analogue, showed 56–63% absolute oral bioavailability in TAO patients receiving an extended-release formulation, indicating that some prostaglandin analogues can achieve high oral bioavailability under specific conditions.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Alpha-lipoic acid, a carboxylic acid-containing cyclic disulfide, has an oral bioavailability of approximately 25–30% in humans, showing that some fatty-acid-like small molecules can exceed the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C23"],
      "claim": "Testosterone undecanoate, a lipophilic long-chain ester prodrug, has an absolute oral bioavailability of about 6.8% in humans, supporting that lipophilic prodrugs with long alkyl chains can have low oral bioavailability due to first-pass metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a bicyclic prostaglandin-like fatty acid with a carboxylic acid, difluoropentyl side chain, ketone, and ether ring. The most transferable experimental evidence comes from nocloprost, a prostaglandin analogue with ~2% absolute oral bioavailability in humans, indicating that this structural class is subject to extensive first-pass metabolism and very low systemic exposure. Positive evidence from lipoic acid and iloprost is less transferable due to structural differences or special formulations/patient populations. Therefore, the query is predicted to have low oral bioavailability (F < 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "All evidence molecules have low Morgan similarity (<0.31).",
    "Conflicting results among prostaglandin analogues (nocloprost low vs iloprost high).",
    "One record (C24) appears to have a mismatched SMILES/compound description."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

